const section=(title,html)=>`<section class="section"><h2>${esc(title)}</h2>${html}</section>`;
const table=(headers,rows,cls='')=>`<div class="table-wrap" tabindex="0" role="region" aria-label="${esc(headers.join(', '))}"><table class="${cls}"><thead><tr>${headers.map(h=>`<th scope="col">${h}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.join(''):`<tr><td colspan="${headers.length}">No records match these filters. Clear filters to show all records.</td></tr>`}</tbody></table></div>`;
const tr=(cells,key='',selected=false)=>`<tr ${selected?'class="selected"':''} ${key?`data-row="${esc(key)}"`:''}>${cells.map(c=>`<td>${c}</td>`).join('')}</tr>`;
const opt=(values,selected,first='All')=>`<option value="">${esc(first)}</option>${values.map(v=>`<option value="${esc(v)}" ${String(v)===String(selected)?'selected':''}>${esc(v)}</option>`).join('')}`;
const btn=(label,action,extra='')=>`<button type="button" data-action="${action}" ${extra}>${esc(label)}</button>`;
const choose=(label,key)=>`<button class="plain-button strong" data-select="${esc(key)}">${esc(label)}</button>`;
const pages={};let catalog, params=new URLSearchParams(location.search), pageName, renderToken=0, activeRows=[], selected='', pagination=0;
let viewState={}; const cache=new Map(),drafts=new Map();
async function data(name){if(cache.has(name))return cache.get(name);const p=fetch(`/staffer-live/approved/data/${name}.json`).then(r=>{if(!r.ok)throw Error(`Could not load ${name} (${r.status}).`);return r.json();}).catch(e=>{cache.delete(name);throw e;});cache.set(name,p);return p;}
function url(view,extra={}){const q=new URLSearchParams();q.set('view',view);for(const k of ['issue','congress','period','bill'])if(params.get(k))q.set(k,params.get(k));for(const[k,v]of Object.entries(extra))if(v!=null&&v!=='')q.set(k,v);return '/?'+q;}
function memberLink(name,label=name,tab='overview'){name=catalog.members.find(m=>m.name===name||m.bio?.bioguide===name)?.name||name;return `<a data-route href="${esc(url('profile',{m:name,tab}))}">${esc(label)}</a>`;}
function patchURL(patch,replace=true){const q=new URLSearchParams(location.search);for(const[k,v]of Object.entries(patch)){if(v==null||v==='')q.delete(k);else q.set(k,v);}history[replace?'replaceState':'pushState'](null,'','/?'+q);params=q;}
/* Build 01: one page head for every view (title, global search, data chip, Compare), the Compare tray on Member desk views. */
const DESK_VIEWS=new Set(['members','member-bills','efficiency','spending','investment','coalition','compare','contact','exports','profile']);
const DESK_TAB_VIEWS=['members','member-bills','efficiency','coalition','compare','contact'];
const HEAD_TITLES={influence:'Influence',industry:'Industry',people:'People & connections','research-bills':'Bills',interactions:'Reported interactions',champions:'Champions',forecasts:'Cosponsorship forecast','cu-fintech':'CU × fintech',methods:'Methods'};
const knownView=v=>Object.prototype.hasOwnProperty.call(HEAD_TITLES,v)||DESK_VIEWS.has(v)||Object.prototype.hasOwnProperty.call(pages,v);const headTitle=v=>Object.prototype.hasOwnProperty.call(HEAD_TITLES,v)?HEAD_TITLES[v]:knownView(v)?'Member desk':'View not found';
const MONTHS=['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
const SECTOR_NAMES={bank:'Bank',credit_union:'Credit union',fintech:'Fintech',crypto:'Crypto',telecom:'Telecom',financial_other:'Other finance'};
const SEARCH_ICON='<svg class="mlk-search__icon" viewBox="0 0 16 16" aria-hidden="true"><circle cx="7" cy="7" r="5"/><path d="m11 11 3.5 3.5"/></svg>',INFO_ICON='<svg viewBox="0 0 16 16" aria-hidden="true"><circle cx="8" cy="8" r="6.5"/><path d="M8 7.2v4M8 4.8v.1"/></svg>';
const IS_MAC=typeof navigator!=='undefined'&&/Mac|iPhone|iPad/.test(navigator.platform||navigator.userAgent||'');
let headInfo=null,searchData=null,searchLoading=null,searchError='',searchTimer2,searchState={rows:[],active:-1};
function dataDate(iso){const m=/^(\d{4})-(\d{2})-(\d{2})/.exec(String(iso||'')),mo=m&&MONTHS[Number(m[2])-1];return mo?`${mo} ${Number(m[3])}, ${m[1]}`:'';}
function compareStore(){try{return window.MelangeCompare||null;}catch{return null;}}
function compareIds(){try{return compareStore()?compareStore().list():[];}catch{return [];}}
function partyDot(party){try{return window.MLK&&window.MLK.partyColor?window.MLK.partyColor(party):'';}catch{return '';}}
function dot(party){const c=partyDot(party);return `<span class="mlk-dot"${c?` style="--mlk-dot:${esc(c)}"`:''}></span>`;}
function memberByBioguide(id){return (catalog&&catalog.members||[]).find(m=>m.bio&&m.bio.bioguide===id)||null;}
function profileHref(name){return '/?'+new URLSearchParams({view:'profile',m:name,tab:'overview'});}
function setHeadInfo(text,label='How to read this'){headInfo=text?{label,text}:null;return '';}
const lede=text=>`<p class="mlk-lede">${esc(text)}</p>`;
function deskTabs(active){try{return window.MLK&&window.MLK.deskTabs?window.MLK.deskTabs(active,{menuId:'mlk-deskmenu'}):'';}catch{return '';}}
function headTitleHTML(){const label=headInfo&&(headInfo.label||'How to read this');return `<h1>${esc(headTitle(pageName))}</h1>${headInfo?`<div class="mlk-anchor"><button type="button" class="mlk-info" aria-haspopup="dialog" aria-expanded="false" aria-controls="mlk-headinfo" data-mlk-toggle="mlk-headinfo">${INFO_ICON}<span>${esc(label)}</span></button><div class="mlk-popover mlk-headinfo" id="mlk-headinfo" role="dialog" aria-label="${esc(label)}" hidden>${headInfo.html||`<p>${esc(headInfo.text||'')}</p>`}</div></div>`:''}`;}
function freshnessHTML(f){const parts=Array.isArray(f.parts)?f.parts:[];return parts.length?parts.map(p=>`<p><b>${esc(p.label)}</b> ${esc(p.text)}</p>`).join(''):'<p>No data-freshness record is available in this build.</p>';}
function compareInner(n){return `Compare${n?`<span class="mlk-badge" aria-hidden="true">${n}</span>`:''}`;}
function pageHead(){const f=(catalog&&catalog.freshness)||{},d=dataDate(f.through),n=compareIds().length;return `<header class="mlk-pagehead${pageName==='influence'?' mlk-dark':''}" id="mlk-pagehead"><div class="mlk-pagehead__title">${headTitleHTML()}</div><div class="mlk-pagehead__tools"><div class="mlk-search mlk-search--kbd mlk-headsearch" id="mlk-headsearch">${SEARCH_ICON}<input id="mlk-search-input" class="mlk-search__input" type="text" role="combobox" aria-autocomplete="list" aria-expanded="false" aria-controls="mlk-search-panel" aria-label="Search members, bills, organizations" placeholder="Search members, bills, organizations" autocomplete="off" spellcheck="false"><kbd class="mlk-kbd" aria-hidden="true">${IS_MAC?'⌘ K':'Ctrl K'}</kbd><div class="mlk-results" id="mlk-search-panel" role="listbox" aria-label="Search results" hidden></div></div><div class="mlk-anchor"><button type="button" class="mlk-chip mlk-datachip" aria-haspopup="dialog" aria-expanded="false" aria-controls="mlk-datapop" data-mlk-toggle="mlk-datapop">${d?`Data through ${esc(d)}`:'Data date unknown'}</button><div class="mlk-popover mlk-popover--end mlk-datapop" id="mlk-datapop" role="dialog" aria-label="Data freshness" hidden>${freshnessHTML(f)}</div></div><a class="mlk-btn mlk-comparebtn" href="${esc(url('compare'))}" data-route aria-label="${n?`Compare, ${n} selected`:'Compare'}">${compareInner(n)}</a></div></header>`;}
function syncCompare(){const ids=compareIds(),btn=$('#mlk-pagehead .mlk-comparebtn');if(btn){btn.innerHTML=compareInner(ids.length);btn.setAttribute('aria-label',ids.length?`Compare, ${ids.length} selected`:'Compare');}syncTray(ids);}
function syncTray(ids=compareIds()){const tray=$('#mlk-tray');if(!tray)return;const on=DESK_VIEWS.has(pageName)&&pageName!=='compare'&&ids.length>0;if(document.body&&document.body.classList)document.body.classList.toggle('mlk-tray-on',on);if(!on){tray.hidden=true;tray.innerHTML='';return;}tray.innerHTML=`<span class="mlk-tray__count">${ids.length} selected</span><ul class="mlk-tray__chips">${ids.map(id=>{const m=memberByBioguide(id),name=m?m.name:id;return `<li class="mlk-tray__chip">${dot(m&&m.party)}<a href="${esc(url('profile',{m:name,tab:'overview'}))}" data-route>${esc(name)}</a><button type="button" class="mlk-tray__remove" data-compare-remove="${esc(id)}" aria-label="Remove ${esc(name)} from Compare"><svg viewBox="0 0 12 12" aria-hidden="true"><path d="m3 3 6 6M9 3 3 9"/></svg></button></li>`;}).join('')}</ul><button type="button" class="mlk-tray__clear" data-compare-clear>Clear</button><a class="mlk-btn mlk-btn--accent mlk-tray__go" href="${esc(url('compare'))}" data-route>Compare ${ids.length} member${ids.length===1?'':'s'} →</a>`;tray.hidden=false;}
function norm(s){return String(s??'').normalize('NFD').replace(/[̀-ͯ]/g,'').toLowerCase();}
function compact(s){return norm(s).replace(/[^a-z0-9]/g,'');}
function loadSearch(){if(searchData||searchLoading)return searchLoading;searchError='';searchLoading=Promise.all([data('bills'),data('industry')]).then(([b,ind])=>{searchData={bills:Object.entries(b.bills||{}).map(([key,x])=>({key,label:x.display||key,title:x.title||'',congress:Number(x.congress)||0,n:norm(`${x.display||''} ${x.title||''}`),c:compact(x.display||key)})),orgs:(ind.companies||[]).map(o=>({id:o.id,name:o.name||o.id,sector:o.sector,n:norm(o.name)}))};}).catch(e=>{searchError=e.message||'Search data could not load.';}).finally(()=>{searchLoading=null;renderResults();});return searchLoading;}
function rankText(hay,q){if(!q)return -1;if(hay.startsWith(q))return 0;const i=hay.indexOf(q);if(i<0)return -1;return /[a-z0-9]/.test(hay[i-1])?2:1;}
function searchRows(raw){const q=norm(raw).trim(),qc=compact(raw),numeric=/\d/.test(qc);if(!q)return [];
 const members=(catalog&&catalog.members||[]).map(m=>{let s=rankText(norm(m.name),q);if(s<0&&rankText(norm(`${m.state||''} ${m.bio&&m.bio.state||''}`),q)>=0)s=3;return s<0?null:{kind:'member',s,label:m.name,meta:[m.chamber,m.bio&&m.bio.state].filter(Boolean).join(' · '),party:m.party,href:profileHref(m.name)};}).filter(Boolean).sort((a,b)=>a.s-b.s||a.label.localeCompare(b.label));
 const bills=searchData?searchData.bills.map(b=>{let s=-1;if(numeric&&b.c===qc)s=0;else if(numeric&&b.c.startsWith(qc))s=1;else{const r=rankText(b.n,q);if(r>=0)s=r+2;}return s<0?null:{kind:'bill',s,label:b.label,meta:b.title,congress:b.congress,href:'/?'+new URLSearchParams({view:'member-bills',bill:b.key})};}).filter(Boolean).sort((a,b)=>a.s-b.s||b.congress-a.congress||a.label.localeCompare(b.label,undefined,{numeric:true})):[];
 const orgs=searchData?searchData.orgs.map(o=>{const s=rankText(o.n,q);return s<0?null:{kind:'org',s,label:o.name,meta:SECTOR_NAMES[o.sector]||o.sector||'',href:'/?'+new URLSearchParams({view:'industry',tab:'organizations',org:o.id})};}).filter(Boolean).sort((a,b)=>a.s-b.s||a.label.localeCompare(b.label)):[];
 const groups=[['member',members,4],['bill',bills,2],['org',orgs,2]],take={};let left=8;for(const[k,list,quota]of groups){take[k]=Math.min(list.length,quota);left-=take[k];}for(const[k,list]of groups){const more=Math.min(left,list.length-take[k]);take[k]+=more;left-=more;}return groups.flatMap(([k,list])=>list.slice(0,take[k]));}
function closeResults(){const panel=$('#mlk-search-panel'),input=$('#mlk-search-input');if(panel&&!panel.hidden){panel.hidden=true;panel.innerHTML='';}if(input){input.setAttribute('aria-expanded','false');input.removeAttribute('aria-activedescendant');}searchState={rows:[],active:-1};}
function renderResults(){const panel=$('#mlk-search-panel'),input=$('#mlk-search-input');if(!panel||!input)return;const q=input.value.trim();if(!q||document.activeElement!==input&&panel.hidden){if(!q)closeResults();return;}const rows=searchRows(q),labels={member:'Members',bill:'Bills',org:'Organizations'};searchState={rows,active:rows.length?0:-1};let html='',last='';rows.forEach((r,i)=>{if(r.kind!==last){html+=`<div class="mlk-results__group" role="presentation">${labels[r.kind]}</div>`;last=r.kind;}html+=`<a class="mlk-results__item" role="option" id="mlk-opt-${i}" data-idx="${i}" href="${esc(r.href)}" data-route tabindex="-1" aria-selected="${i===0}">${r.kind==='member'?dot(r.party):''}<span class="mlk-results__main">${esc(r.label)}</span><span class="mlk-results__meta">${esc(r.meta)}</span></a>`;});const status=searchError?`<div class="mlk-results__empty" role="status">Bills and organizations could not load. ${esc(searchError)}</div>`:!searchData?'<div class="mlk-results__empty" role="status">Loading bills and organizations…</div>':'';panel.innerHTML=(rows.length?html:status?'':'<div class="mlk-results__empty" role="status">No matches</div>')+status;panel.hidden=false;input.setAttribute('aria-expanded','true');if(rows.length)input.setAttribute('aria-activedescendant','mlk-opt-0');else input.removeAttribute('aria-activedescendant');}
function setActive(i){const rows=searchState.rows;if(!rows.length)return;searchState.active=(i+rows.length)%rows.length;for(const o of $$('#mlk-search-panel [role=option]'))o.setAttribute('aria-selected',String(Number(o.dataset.idx)===searchState.active));const opt=document.getElementById('mlk-opt-'+searchState.active);$('#mlk-search-input').setAttribute('aria-activedescendant','mlk-opt-'+searchState.active);if(opt&&opt.scrollIntoView)opt.scrollIntoView({block:'nearest'});}
function focusSearch(){const input=$('#mlk-search-input');if(!input)return;try{if(window.MLK&&window.MLK.closeAll)window.MLK.closeAll({restoreFocus:false});}catch{}try{window.focus();}catch{}input.focus();input.select();loadSearch();if(input.value.trim())renderResults();}
function go(href){history.pushState(null,'',href);pagination=0;selected='';document.body.classList.remove('nav-open');$('#menu').setAttribute('aria-expanded','false');$('#content').inert=false;render();window.scrollTo(0,0);}
function header(title,description='',actions=''){return `<header class="page-head mlk-subhead"><div><h2>${esc(title)}</h2>${description?`<p>${esc(description)}</p>`:''}</div>${actions?`<div class="head-actions">${actions}</div>`:''}</header>`;}
function nav(){const main=[['influence','Influence'],['members','Members'],['industry','Industry'],['people','People'],['research-bills','Bills'],['interactions','Reported interactions'],['champions','Champions'],['forecasts','Forecasts'],['cu-fintech','CU × fintech'],['methods','Methods']];$('#navlinks').innerHTML=main.map(([id,label],i)=>`${i===4?'<div class="nav-group">Research</div>':''}${i===9?'<div class="nav-group"></div>':''}<a class="nav-link" data-route href="${esc(url(id))}" ${id===(DESK_VIEWS.has(pageName)?'members':pageName)?'aria-current="page"':''}><svg viewBox="0 0 24 24" aria-hidden="true"><path d="${catalog.icons[label]||catalog.icons.Members}"></path></svg><span>${label}</span></a>`).join('');}
function tabs(items,active,extra={}){return `<nav class="tabs" aria-label="${active==='profile'?'Dossier':'Workspace'} sections">${items.map(([id,label])=>`<a data-route href="${esc(url(id,extra))}" ${id===active?'aria-current="page"':''}>${esc(label)}</a>`).join('')}</nav>`;}
/* Native Member desk pages: the shared Member desk tab group; their description moves behind "How to read this". */
function workspace(title,desc=''){if(desc)setHeadInfo(desc);return deskTabs(pageName)+(DESK_TAB_VIEWS.includes(pageName)?'':`<h2 class="mlk-viewtitle">${esc(title)}</h2>`);}
function scope(){return `<div class="scope"><label>Issue<select data-scope="issue">${opt(catalog.cats,params.get('issue'),'All issues')}</select></label><label>Congress<select data-scope="congress">${opt(['119','118','117'],params.get('congress'),'All retained')}</select></label><label>From<input type="date" data-scope="period" value="${esc(params.get('period')||'')}"></label><span class="meta">Public records · dates shown at source</span></div>`;}
function pageSelection(rows,size,key='name',fallback=''){pagination=Math.min(pagination,Math.max(0,Math.ceil(rows.length/size)-1));const wanted=params.get('selected')||fallback,index=rows.findIndex(r=>String(r[key])===String(wanted));if(index>=0)pagination=Math.floor(index/size);return rows[index>=0?index:pagination*size];}
function pageControls(count,size){const start=pagination*size;return `<div class="pagination"><span>${count?`${num(start+1)}–${num(Math.min(start+size,count))} of ${num(count)}`:'0'} records</span><div>${btn('Previous','previous',pagination===0?'disabled':'')}${btn('Next','next',(start+size>=count)?'disabled':'')}</div></div>`;}
function bar(value,max,secondary=false){return value==null?'<span class="muted">Unknown</span>':`<span class="bar-cell ${secondary?'secondary':''}"><span class="bar-track"><i style="width:${Math.min(100,value/Math.max(1,max)*100)}%"></i></span><b>${num(value)}</b></span>`;}
function billURL(key){const[c,t,n]=String(key).split(':'),type={hr:'house-bill',s:'senate-bill',hres:'house-resolution',sres:'senate-resolution',hjres:'house-joint-resolution',sjres:'senate-joint-resolution',hconres:'house-concurrent-resolution',sconres:'senate-concurrent-resolution'}[t];return type?`https://www.congress.gov/bill/${c}th-congress/${type}/${n}`:'';}
function billKey(b){if(b.key)return b.key;const s=String(b.bill||'').toLowerCase().replace(/[^a-z0-9]/g,'');const a=s.match(/^([a-z]+)(\d+)$/);return a?`${b.congress}:${a[1]}:${a[2]}`:'';}
function readStore(key,fallback={}){try{return JSON.parse(localStorage.getItem(key))||fallback;}catch{return fallback;}}
function manual(name){return readStore('mdesk_manual_v1')[name]||{};}
function saveManual(name,patch){const all=readStore('mdesk_manual_v1'),next={...all,[name]:{...(all[name]||{}),...patch}};localStorage.setItem('mdesk_manual_v1',JSON.stringify(next));}
function profileFor(name){const m=catalog.members.find(m=>m.name===name);if(!m)throw Error('This member is not in the retained directory.');return data('member-'+m.id);}
function recordScope(rows){return rows.filter(r=>(!params.get('issue')||r.areas?.includes(params.get('issue')))&&(!params.get('congress')||String(r.congress)===params.get('congress'))&&(!params.get('period')||(r.date!=='Date unavailable'&&r.date>=params.get('period'))));}
async function records(m,scoped=true){const live=await data('bills'),out=[];for(const b of m.bills||[]){const l=live.bills?.[billKey(b)],co=l?.cosponsors?.find(c=>c.bioguide===m.bio?.bioguide);out.push({kind:/^LTR/i.test(b.bill)?'Letter':b.role==='sponsor'?'Sponsorship':'Cosponsorship',title:`${b.bill} · ${b.title||'Title unavailable'}`,date:date(b.role==='sponsor'?l?.introduced_date:co?.date),url:b.url||l?.url,excerpt:b.summary||l?.summary||'',areas:b.areas,congress:b.congress,reason:`Recorded ${b.role||'legislative role'}; bill membership does not establish personal contact.`});}for(const a of m.articles||[])out.push({kind:a.source==='hearing'?'Committee actions':'Public statements',title:a.title,date:date(a.date),url:a.url,excerpt:a.excerpt||a.text||a.snippet||'',areas:a.cats,congress:a.date?Math.floor((Number(a.date.slice(0,4))-1789)/2)+1:null,reason:a.exclusion?`Excluded from scoring: ${a.exclusion}`:a.rel||'Retained public record. Read the original source for context.',source:a.source});const seen=new Set();const rows=out.filter(r=>{const key=[r.kind,r.url||r.title,r.date].join('|');if(seen.has(key))return false;seen.add(key);return true;}).sort((a,b)=>(b.date==='Date unavailable'?'':b.date).localeCompare(a.date==='Date unavailable'?'':a.date));return scoped?recordScope(rows):rows;}
function timeline(rows,limit=3,compact=false){return rows.length?`<ol class="timeline ${compact?'compact':''}">${rows.slice(0,limit).map((r,i)=>`<li><time>${esc(r.date)}</time><div><small>${esc(r.kind||'Public record')}</small><p>${esc(r.title)}</p><small>${source(r.url)}${compact?'':` · ${esc(r.reason||'')}`}</small></div></li>`).join('')}</ol>`:missing('No retained public actions match this scope.');}
function role(m){return `<p>${esc(m.chamber)} · ${esc(m.district)}</p><p class="muted">${(m.committees||[]).slice(0,3).map(c=>`${esc(c.name)}${c.role?' · '+esc(c.role):''}`).join('; ')||'Committee assignments unavailable.'}</p>`;}
function economy(m){const e=m.community?.estimates||{},ind=m.industry||{};return table(['Measure','Value','Context / period'],[tr(['Median household income',money(e.median_household_income||m.demo?.income),`${m.community?.vintage||'Unknown'} · ACS`]),tr(['Covered jobs',num(ind.employment?.total),`${ind.latest_year||'Unknown'} · LEHD LODES`]),tr(['Finance & insurance',pct(ind.makeup?.CNS10),'Share of covered jobs']),tr(['Credit-union branches',num(m.financial?.cus?.n_branches),'Retained financial institution snapshot'])]);}
function sourceList(rows){return rows.length?`<ul class="source-list">${rows.slice(0,5).map(r=>`<li>${source(r.url,r.title)}<small>${esc(r.date)}</small></li>`).join('')}</ul>`:missing('No sources in this scope.');}
function advanced(m){return `<details><summary>Model details & complete analytical dossier</summary><p>Model ranks describe relative position in the retained model. They are not probabilities of persuasion.</p><p><a href="/staffer-live/approved/advanced-desk.html?m=${encodeURIComponent(m.name)}" target="_blank" rel="noopener">Open the complete analytical workspace</a></p></details>`;}
function engagement(m){const t=manual(m.name).tracker||{};return `<div class="engagement"><div><small>Owner</small>${esc(t.owner||'Unassigned')}</div><div><small>Next step</small>${esc(t.next||'Not recorded')}</div><div><small>Due</small>${esc(t.due||'Not set')}</div>${memberLink(m.name,'Edit follow-up','notes')}</div>`;}
function briefAside(m,rows){const t=manual(m.name).tracker||{};return section('Meeting objective',`<p>${esc(t.objective||'No meeting objective recorded.')}</p>`)+section('Open questions',`<p class="prewrap">${esc(t.questions||'No open questions recorded.')}</p>`)+section('Owner & next step',`<p><b>${esc(t.owner||'Unassigned')}</b></p><p>${esc(t.next||'No next step recorded.')}</p><p class="meta">Due ${esc(t.due||'not set')} · Team note</p><p>${memberLink(m.name,'Edit meeting brief','notes')}</p>`)+section('Sources in this brief',sourceList(rows.slice(0,3)));}
/* Notes & follow-up is the one native profile page; its tabs repeat the v2 profile's six (desk-profile.js TABS) so each lands where its label says. */const profileTabs=[['overview','Overview'],['bills','Bills'],['access','Access'],['district','District'],['coverage','Press & coverage'],['sources','Sources & method'],['notes','Notes & follow-up']];
async function profile(){const m=await profileFor(params.get('m')||'Andy Barr'),r=await records(m),all=await records(m,false),tab=params.get('tab')||location.hash.replace('#profile-','')||'overview';viewState={m,r,all,tab};const body=profileBody(m,r,all,tab);return `<header class="page-head profile-head"><div class="identity"><div><h2 class="profile-name">${esc(m.name)}</h2><p>${esc(m.chamber)} · ${esc(m.party)} · ${esc(m.district)}</p></div></div><div class="profile-context">${scope()}<div class="head-actions"><a data-route href="${esc(url('members'))}">All members</a><a data-route href="${esc(url('exports',{m:m.name}))}">Prepare brief</a></div></div></header><div class="profile-tabbar"><nav class="mlk-tabs profile-tabs" aria-label="Member profile sections">${profileTabs.map(([id,label])=>`<a data-route href="${esc(url('profile',{m:m.name,tab:id}))}" ${tab===id?'aria-current="page"':''}>${esc(label)}</a>`).join('')}</nav></div>${body}`;}
function profileBody(m,r,all,tab){
 if(tab==='overview')return `<div class="split"><div>${section('Role & jurisdiction',role(m))}${section('Documented actions & timeline',timeline(r))}${section('Economic context',economy(m))}${engagement(m)}${advanced(m)}</div><aside class="aside">${briefAside(m,r)}</aside></div>`;
 if(tab==='background'){const bio=m.bio?.wikipedia||{},sum=bio.summary||{};return `<div class="split"><div>${section('Role & career record',`<p>${esc(sum.overview||'Biographical overview unavailable.')}</p><div class="rule"><h3>Public service</h3><p>${esc(sum.career||'A dated role history is unavailable in this record.')}</p><p class="meta">${source(bio.url,'Biographical source')} · revision ${date(bio.revision_timestamp)}</p></div>${table(['Committee jurisdiction','Recorded role'],(m.committees||[]).map(c=>tr([esc(c.name),esc(c.role||'Member')])) )}`)}${section('Issue & jurisdiction',table(['Issue','Retained bill records'],catalog.cats.filter(c=>(m.bills||[]).some(b=>b.areas?.includes(c))).map(c=>tr([esc(c),num(m.bills.filter(b=>b.areas?.includes(c)).length)]))))}</div><aside class="aside">${section('Biography',`<p>${esc(sum.early_life||'Early background unavailable.')}</p>`)}${section('Official sources',`<p>${source(m.bio?.url,'Official congressional website')}</p><p>${source(bio.url,'Biography & revision')}</p>`)}${advanced(m)}</aside></div>`;}
 if(tab==='demographics'){const i=m.industry||{},sectors=[['CNS10','Finance & insurance'],['CNS05','Manufacturing'],['CNS16','Health care'],['CNS15','Education'],['CNS07','Retail trade']];return `<div class="split"><div>${section('District economy',`<p>${esc(m.district_brief?.p1||'District economic brief unavailable.')}</p>${economy(m)}`)}${section('Employment benchmarks',`<p class="meta">${i.latest_year||'Unknown'} · share of covered jobs · district and national comparison</p>${table(['Industry','District share','National share¹'],sectors.map(([k,n])=>tr([n,bar(i.makeup?.[k]==null?null:100*i.makeup[k],30),bar(i.makeup?.[k]!=null&&i.lq?.[k]>0?100*i.makeup[k]/i.lq[k]:null,30,true)])),'benchmarks')}<p class="table-note">¹ National share derived from the retained location quotient. Bars share a 0–30% scale.</p>`)}</div><aside class="aside">${section('Financial institutions',`<div class="institution-list"><div><b>${num(m.financial?.cus?.n_branches)}</b><small>Credit-union branches</small></div><div><b>${num(m.financial?.banks?.n_branches)}</b><small>Bank branches · allocated</small></div></div><p class="rule">Largest retained credit union: ${esc(m.financial?.cus?.top1_name||'Unknown')}</p>${missing('Institution coordinates are unavailable; a geographic map cannot be plotted from these records.')}`)}${section('Coverage',`<p>${esc(m.community?.survey||'Survey unavailable')} · ${m.community?.vintage||'Unknown vintage'}</p><p class="meta">Employment uses ${i.latest_year||'unknown'} workplace geography. District redraws and geographic allocation can affect comparisons.</p>`)}</aside></div>`;}
 if(tab==='behavior'){const picked=r[Number(params.get('selected'))]||r[0];const kinds=['Sponsorship','Cosponsorship','Committee actions','Public statements'];return `<div class="split"><div>${section('Documented behavior',table(['Action type','Observed actions','Eligible denominator','Period / coverage'],kinds.map(k=>{const rs=r.filter(a=>a.kind===k);return tr([k,num(rs.length),'Unavailable',rs.length?`${esc(rs[rs.length-1].date)} – ${esc(rs[0].date)}`:'Unknown']);})))}${section('Dated action timeline',r.length?`<ol class="timeline">${r.slice(0,8).map((a,i)=>`<li><time>${esc(a.date)}</time><div>${choose(a.title,i)}<small>${esc(a.kind)} · ${source(a.url)}</small></div></li>`).join('')}</ol>`:missing('No events in this scope.'))}<details><summary>Interpretive research & coverage notes</summary><p>Retained records describe documented actions. An eligible denominator is unavailable, so no rates or predictions are shown.</p>${advanced(m)}</details></div><aside class="aside">${section('Selected source',picked?`<p>${esc(picked.title)}</p><p class="meta">${esc(picked.date)} · ${esc(picked.kind)}</p><p>${source(picked.url)}</p><p class="rule">${esc(picked.reason)}</p>`:missing('No event in this scope.'))}${section('Original excerpt',picked?.excerpt?`<p>${esc(picked.excerpt)}</p>`:missing('An original excerpt is not retained. Open the linked source.'))}</aside></div>`;}
 if(tab==='positions')return section('Legislative-action timeline',timeline(r.filter(a=>['Sponsorship','Cosponsorship','Letter'].includes(a.kind)),3))+section('Bills & recorded roles',table(['Bill / official title','Role','Congress','Sources'],(m.bills||[]).filter(b=>(!params.get('issue')||b.areas?.includes(params.get('issue')))&&(!params.get('congress')||String(b.congress)===params.get('congress'))).map(b=>tr([`<a data-route href="${esc(url('member-bills',{bill:billKey(b)}))}">${esc(b.bill)}</a><small>${esc(b.title)}</small>`,esc(b.role),esc(b.congress),source(b.url||billURL(billKey(b)))]))));
 if(tab==='access')return `<div class="split"><div>${section('Staff roster',table(['Person','Retained role','Evidence / route'],(m.staffdir||[]).map(s=>tr([esc(s.n),esc(s.t),`<a data-route href="${esc(url('people',{office:m.name,person:'quorum:'+s.id}))}">Inspect source & find route</a>`]))))}${section('Relationship paths',`<p>Resolve the staff member and starting contact in People to inspect a route built from dated workplace evidence.</p><p><a data-route href="${esc(url('people',{office:m.name}))}">Open ${esc(m.name)}’s office in People</a></p>`)}</div><aside class="aside">${section('Contact history',contactHistory(m.name))}${section('Evidence scope',`<p>Directory roles reflect the source date. Workplace overlap does not establish a personal relationship.</p>`)}</aside></div>`;
 if(tab==='coverage'){const rows=r.filter(a=>['Public statements','Committee actions'].includes(a.kind)),groups=new Map();for(const a of rows){const k=a.date+'|'+a.title.toLowerCase().replace(/[^a-z0-9]/g,'');if(!groups.has(k))groups.set(k,[]);groups.get(k).push(a);}return `<div class="split"><div>${section('Past coverage',`<p class="table-note">${groups.size} dated events · repeated channels grouped by date and title</p>${[...groups.values()].map((g,i)=>`<details ${i===0?'open':''}><summary>${esc(g[0].date)} · ${esc(g[0].title)}</summary><p>${esc(g[0].reason)}</p>${sourceList(g)}</details>`).join('')||missing('No coverage matches this scope.')}`)}</div><aside class="aside">${section('Inclusion & source coverage',`<p>Events retain their original source links. Duplicate channels do not create independent public actions.</p><p class="rule">${num(m.articles?.length)} retained source records before the current filters.</p>`)}</aside></div>`;}
 if(tab==='notes')return noteEditor(m);
 return sourcesPage(m,all);
}
function sourcesPage(m,all){const groups=new Map();for(const r of all){const key=r.source||(/Sponsorship|Cosponsorship/.test(r.kind)?'Congress.gov':r.kind);if(!groups.has(key))groups.set(key,[]);groups.get(key).push(r);}return section('Source coverage',table(['Source','Retained records','Latest record','Limitations'],[...groups].map(([key,rows])=>tr([esc(key),num(rows.length),esc(rows[0]?.date),'Source coverage varies; absence is not neutrality.']))))+`<details><summary>Public record</summary><p>Legislation, reported filings and public statements retain their dates and sources. A filing reference does not establish contact, support or endorsement.</p></details><details><summary>Model estimates & scenarios</summary><p>Ranks are relative measures. Forecasts and budget scenarios depend on the retained population, period and assumptions. They are not causal estimates.</p>${advanced(m)}</details><details><summary>Local notes & exports</summary><p>Engagement records use this browser’s existing local tracker. They are saved on this device, with no shared synchronization.</p></details>`;}
function contactHistory(name){const cs=manual(name).tracker?.contacts||[];return cs.length?`<ul class="source-list">${[...cs].sort((a,b)=>(b.date||'').localeCompare(a.date||'')).slice(0,8).map(c=>`<li><b>${esc(c.date||'Date not set')}</b><p>${esc(c.outcome||c.next||'No outcome recorded')}</p><small>${esc(c.owner||'Owner unassigned')} · ${esc(c.sourceType||'Team note')}</small></li>`).join('')}</ul>`:missing('No contact records saved on this device.');}
function noteEditor(m){const saved=manual(m.name),t=drafts.get(m.name)||saved.tracker||{};return `<div class="split notes-layout"><aside>${section('Follow-up ledger',contactHistory(m.name))}${section('Saved record',`<p>${esc(saved.tracker?.owner||'Owner unassigned')}</p><p class="meta">${saved.tracker?.updatedAt?'Updated '+date(saved.tracker.updatedAt):'No update timestamp recorded'}</p><p>${esc(saved.note||'No general note recorded.')}</p>`)}</aside><div>${section('Meeting brief & next step',`<form id="note-form" class="form-stack"><label class="field">Meeting objective<textarea name="objective">${esc(t.objective||'')}</textarea></label><label class="field">Open questions<textarea name="questions">${esc(t.questions||'')}</textarea></label><div class="inline-fields"><label class="field">Owner<input name="owner" value="${esc(t.owner||'')}"></label><label class="field">Due date<input name="due" type="date" value="${esc(t.due||'')}"></label></div><label class="field">Next step<input name="next" value="${esc(t.next||'')}"></label><div class="inline-fields"><label class="field">Status<select name="status">${['Not contacted','To do','In progress','Waiting','Complete'].map(s=>`<option ${s===t.status?'selected':''}>${s}</option>`).join('')}</select></label><label class="field">Source links<input name="sources" value="${esc(t.sources||'')}"></label></div><button class="primary" type="submit">Save on this device</button><p id="save-status" class="status" role="status">${drafts.has(m.name)?'Unsaved changes':t.updatedAt?'Saved on this device':'Local notes · not shared'}</p></form>`)}${section('Log a contact',`<form id="contact-form" class="form-stack"><div class="inline-fields"><label class="field">Contact date<input name="date" type="date" required></label><label class="field">Owner<input name="owner" value="${esc(t.owner||'')}" required></label></div><label class="field">Outcome / next step<textarea name="outcome" required></textarea></label><label class="field">Source reference<input name="source"></label><button type="submit">Add contact record</button><p id="contact-status" class="status" role="status">Team note · saved on this device</p></form>`)}</div></div>`;}
async function directory(){const search=(params.get('q')||'').toLowerCase(),ch=params.get('chamber')||'',committee=params.get('committee')||'',stance=params.get('stance')||'',priority=params.get('priority')||'';let rows=catalog.members.filter(m=>(!search||`${m.name} ${m.district} ${m.committee?.on||''}`.toLowerCase().includes(search))&&(!ch||m.chamber===ch)&&(!committee||m.committees?.some(c=>c.name===committee))&&(!stance||m.overall_stance===stance)&&(!priority||manual(m.name).tracker?.status===priority));if(params.get('issue')){const ix=catalog.cats.indexOf(params.get('issue'));rows=rows.filter(m=>m.stances?.[ix]&&m.stances[ix]!=='-');}const sort=params.get('sort')||'name';rows.sort((a,b)=>sort==='rank'?(a.rank??9999)-(b.rank??9999):sort==='latest'?(b.latest||'').localeCompare(a.latest||''):a.name.localeCompare(b.name));activeRows=rows;selected=pageSelection(rows,7)?.name||'';const shown=rows.slice(pagination*7,pagination*7+7);const m=selected?await profileFor(selected):null,r=m?await records(m):[];return workspace('Members','Find members by jurisdiction, public evidence and your next action.')+`<div class="filters"><label>Search member or district<input type="search" data-filter="q" value="${esc(params.get('q')||'')}" placeholder="Search member, district or committee"></label><label>Chamber<select data-filter="chamber">${opt(['House','Senate'],ch,'All chambers')}</select></label><label>Legislative area<select data-filter="issue">${opt(catalog.cats,params.get('issue'),'All areas')}</select></label><label>Committee<select data-filter="committee">${opt([...new Set(catalog.members.flatMap(m=>m.committees?.map(c=>c.name)||[]))].sort(),committee,'All committees')}</select></label><label>Sort by<select data-filter="sort">${[['name','Name'],['latest','Latest evidence'],['rank','Model rank']].map(([v,n])=>`<option value="${v}" ${sort===v?'selected':''}>${n}</option>`).join('')}</select></label><details class="filter-details"><summary>Advanced filters & columns</summary><div><label>Retained model classification<select data-filter="stance"><option value="">All classifications</option>${Object.entries({C:'Champion',F:'Defender',A:'Ally',H:'Highly persuadable',P:'Persuadable',G:'Lean persuadable',T:'True neutral',L:'Lean skeptic',N:'Neutral',S:'Skeptic',K:'Highly skeptical',O:'Opponent','-':'Unknown'}).map(([v,n])=>`<option value="${v}" ${stance===v?'selected':''}>${n}</option>`).join('')}</select></label><label>Follow-up status<select data-filter="priority">${opt(['Not contacted','To do','In progress','Waiting','Complete'],priority,'All priorities')}</select></label><label><input type="checkbox" id="model-column" ${params.get('model')?'checked':''}> Model rank column</label></div></details>${btn('Clear filters','clear')}</div><div class="split wide-main"><div>${table(['Member','Committee role','Evidence date','Owner / next action',...(params.get('model')?['Model rank']:[])],shown.map(m=>{const t=manual(m.name).tracker||{};return tr([`<div class="member-cell">${choose(m.name,m.name)}<small>${esc(m.chamber)} · ${esc(m.party)} · ${esc(m.bio?.state||m.state)}${m.chamber==='House'?'–'+esc(m.district.match(/District (\d+)/)?.[1]||'At large'):''}</small></div>`,`<div class="committee-cell">${esc(m.committees?.[0]?.name||'Unknown')}<small>${esc(m.committees?.find(c=>c.role)?.role||'Member')}</small></div>`,esc(date(m.latest)),`${esc(t.owner||'Unassigned')}<small>${esc(t.next||'No next action')}</small>`,...(params.get('model')?[`<span class="numeric">${num(m.rank)}</span>`]:[])],m.name,m.name===selected); }),'directory')}${pageControls(rows.length,7)}<p class="table-note">Select a row to preview its evidence. Open the dossier for the complete record.</p></div><aside class="aside">${section('Evidence preview',m?`<div class="detail-heading"><h2>${esc(m.name)}</h2><p>${esc(m.district)}</p><p>${memberLink(m.name,'Open member dossier')}</p></div>${section('Recent public evidence',timeline(r,3,true))}${section('Engagement',contactHistory(m.name))}`:missing('Choose a member after clearing the filters.'))}</aside></div>`;}
function routeName(){if(params.get('view'))return params.get('view');if(params.get('m'))return 'profile';if(params.get('v'))return {desk:'members',industry:'industry',staffer:'people'}[params.get('v')]||'influence';return {'/lobby-bills.html':'research-bills','/lobby-interactions.html':'interactions','/lobby-champions.html':'champions','/lobby-forecast.html':'forecasts','/lobby-screen.html':'cu-fintech'}[location.pathname]||'influence';}
/* Routing (build 01): member-desk views embed original-desk.html with deskview=<legacy or registry view>;
   efficiency takes mode=investment|spending (spending/investment stay as aliases); influence passes issue, congress,
   period, member, net, color, links, layout; people passes office/person/route params and tab. */
async function render(){const token=++renderToken,started=performance.now();params=new URLSearchParams(location.search);pageName=routeName();headInfo=null;closeResults();document.title='MELANGE · '+(pageName==='profile'?(params.get('m')||'Member dossier'):knownView(pageName)?pageName.replace(/-/g,' '):'View not found');nav();const root=$('#content');root.className='';root.setAttribute('aria-busy','true');const oldHead=root.querySelector('#mlk-pagehead');if(oldHead&&!root.querySelector('.mlk-frame-host'))oldHead.outerHTML=pageHead();else root.innerHTML=pageHead()+'<div class=loading role=status>Loading records…</div>';try{let html;const originalViews=Object.assign(Object.create(null),{members:'ranked','member-bills':'bills',efficiency:'efficiency',spending:'efficiency',investment:'efficiency',coalition:'coalition',compare:'compare',profile:'member'});const originalResearch=['industry','champions','research-bills','interactions','cu-fintech'];if((originalViews[pageName]&&!(pageName==='profile'&&params.get('tab')==='notes'))||originalResearch.includes(pageName)){root.className='embedded';const q=new URLSearchParams(params);let file=pageName;if(originalViews[pageName]){file='desk';q.set('deskview',originalViews[pageName]);if(originalViews[pageName]==='efficiency')q.set('mode',pageName==='spending'||(pageName==='efficiency'&&params.get('mode')==='spending')?'spending':'investment');q.set('member',q.get('m')||'Andy Barr');q.delete('m');}html=`<div class="mlk-frame-host"><iframe class="engine-frame" data-view="${esc(pageName)}" title="${esc(pageName==='profile'?'Member dossier':pageName.replace(/-/g,' '))}" src="/staffer-live/approved/original-${file}.html?${esc(q)}${esc(location.hash)}"></iframe></div>`;}else if(pageName==='influence'||pageName==='people'){root.className='embedded'+(pageName==='influence'?' mlk-view-dark':'');let person=params.get('person')||'',routeTarget=params.get('route_target')||'',sourceOnly=params.get('source_only')||'';if(pageName==='people'&&person.startsWith('quorum:')){try{const response=await fetch('/api/staffer-person-link?id='+encodeURIComponent(person));if(!response.ok)throw Error('Person lookup unavailable');const resolved=await response.json();person=resolved.person_id||person;routeTarget=resolved.route_available?resolved.person_id:'';sourceOnly=routeTarget?'':'1';}catch{sourceOnly='1';}}const peopleQ=new URLSearchParams({office:params.get('office')||params.get('s')||'',person,route_target:routeTarget,source_only:sourceOnly,...Object.fromEntries(['route_origin','route_model','route_count','work_sources','alternative_strategy','avoid_people'].filter(k=>params.has(k)).map(k=>[k,params.get(k)]))});if(['network','directory','sources'].includes(params.get('tab')))peopleQ.set('tab',params.get('tab'));const influenceQ=new URLSearchParams({issue:params.get('issue')||'',congress:params.get('congress')||'',period:params.get('period')||''});for(const k of ['member','net','color','links','layout','coal'])if(params.get(k))influenceQ.set(k,params.get(k));html=`<div class="mlk-frame-host"><iframe class="engine-frame" data-view="${esc(pageName)}" title="${pageName==='people'?'People & connections':'Influence network'}" src="/staffer-live/approved/${pageName==='people'?'people':'network'}.html?${esc(pageName==='people'?peopleQ:influenceQ)}"></iframe></div>`;}else html=Object.prototype.hasOwnProperty.call(pages,pageName)?await pages[pageName]():`<section class="mlk-state mlk-notfound"><h2 class="mlk-viewtitle">This view does not exist</h2>${missing(`No view is named "${pageName}".`)}<a class="mlk-btn" data-route href="${esc(url('members'))}">Go to Members</a></section>`;if(token!==renderToken)return;root.innerHTML=pageHead()+html;root.dataset.renderMs=Math.round(performance.now()-started);root.removeAttribute('aria-busy');$('#announcer').textContent=`${document.title} loaded`;syncTray();if(!root.classList.contains('embedded'))attach();}catch(e){if(token!==renderToken)return;root.removeAttribute('aria-busy');root.innerHTML=pageHead()+`<section class="mlk-state mlk-state--error" role="alert"><h2 class="mlk-viewtitle">This view could not load</h2>${missing(e.message)}${btn('Retry','retry','class="mlk-btn"')}</section>`;syncTray();}}
function attach(){const ptabs=$('.profile-tabs'),pcur=ptabs&&ptabs.querySelector('[aria-current=page]');if(pcur&&ptabs.scrollWidth>ptabs.clientWidth)ptabs.scrollLeft+=pcur.getBoundingClientRect().right-ptabs.getBoundingClientRect().right;const form=$('#note-form');if(form){form.oninput=()=>{drafts.set(viewState.m.name,Object.fromEntries(new FormData(form)));$('#save-status').textContent='Unsaved changes';};form.onsubmit=e=>{e.preventDefault();const status=$('#save-status');status.textContent='Saving…';try{const fields=Object.fromEntries(new FormData(form)),old=manual(viewState.m.name).tracker||{};saveManual(viewState.m.name,{tracker:{...old,...fields,issue:params.get('issue')||'',congress:params.get('congress')||'',updatedAt:new Date().toISOString()}});drafts.delete(viewState.m.name);status.textContent='Saved on this device';status.classList.remove('failed');}catch{status.textContent='Save failed. Your draft is still here. Free browser storage and retry.';status.classList.add('failed');}};}const contact=$('#contact-form');if(contact)contact.onsubmit=e=>{e.preventDefault();try{const t=manual(viewState.m.name).tracker||{},fields=Object.fromEntries(new FormData(contact));saveManual(viewState.m.name,{tracker:{...t,contacts:[...(t.contacts||[]),{...fields,id:crypto.randomUUID(),office:viewState.m.name,issue:params.get('issue')||'',due:t.due||'',sourceType:'Team note',createdAt:new Date().toISOString()}]}});contact.reset();$('#contact-status').textContent='Contact saved on this device';}catch{$('#contact-status').textContent='Save failed. Your contact draft has been preserved. Retry after freeing browser storage.';}};pages[pageName]?.attach?.();}
document.addEventListener('click',e=>{const link=e.target.closest('a[data-route]');if(link&&!e.ctrlKey&&!e.metaKey&&!e.shiftKey&&e.button===0){e.preventDefault();go(link.getAttribute('href'));return;}const row=e.target.closest('tr[data-row]');const pick=e.target.closest('[data-select]')||(row&&!e.target.closest('a,input,button')?row.querySelector('[data-select]'):null);if(pick){selected=pick.dataset.select;patchURL({selected});render();return;}const act=e.target.closest('[data-action]')?.dataset.action;if(act==='next'||act==='previous'){pagination+=act==='next'?1:-1;patchURL({selected:''});render();}else if(act==='retry')render();else if(act==='clear'){const q=new URLSearchParams({view:pageName});for(const k of ['m','tab','bill'])if(params.get(k))q.set(k,params.get(k));history.pushState(null,'','/?'+q);pagination=0;render();}else if(act)pages[pageName]?.action?.(act,e);});
let searchTimer;document.addEventListener('input',e=>{if(!e.target.matches('input[type=search][data-filter]'))return;const key=e.target.dataset.filter,value=e.target.value;clearTimeout(searchTimer);searchTimer=setTimeout(async()=>{patchURL({[key]:value,selected:''});pagination=0;await render();const input=document.querySelector('input[data-filter='+key+']');if(input){input.focus();input.setSelectionRange(value.length,value.length);}},220);});
document.addEventListener('change',e=>{const key=e.target.dataset.filter||e.target.dataset.scope;if(key){clearTimeout(searchTimer);patchURL({[key]:e.target.value,selected:''});pagination=0;render();}if(e.target.id==='model-column'){patchURL({model:e.target.checked?'1':''});render();}});
$('#menu').onclick=()=>{const on=document.body.classList.toggle('nav-open');$('#menu').setAttribute('aria-expanded',String(on));$('#content').inert=on;if(on)$('#navigation a').focus();};document.addEventListener('keydown',e=>{if(e.key==='Tab'&&document.body.classList.contains('nav-open')){const controls=[$('#menu'),...$$('#navigation a')],i=controls.indexOf(document.activeElement);e.preventDefault();controls[(i+(e.shiftKey?-1:1)+controls.length)%controls.length].focus();}if(e.key==='Escape'&&document.body.classList.contains('nav-open')){$('#menu').click();$('#menu').focus();}});window.addEventListener('popstate',()=>{pagination=0;render();});
/* Global search (Ctrl/Cmd+K), tray actions. Kit popovers (data chip, How to read this, desk menu) are wired by ui-kit.js. */
document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&!e.altKey&&!e.shiftKey&&(e.key==='k'||e.key==='K')){e.preventDefault();focusSearch();return;}if(!e.target||e.target.id!=='mlk-search-input')return;const panel=$('#mlk-search-panel'),open=panel&&!panel.hidden;if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();if(!open){renderResults();return;}setActive(searchState.active+(e.key==='ArrowDown'?1:-1));}else if(e.key==='Enter'){e.preventDefault();clearTimeout(searchTimer2);const keep=searchState.active;renderResults();if(keep>0)setActive(keep);const r=searchState.rows[Math.max(0,searchState.active)];if(r){closeResults();e.target.blur();go(r.href);}}else if(e.key==='Escape'){if(open){e.preventDefault();e.stopImmediatePropagation();closeResults();}else if(e.target.value)e.target.value='';}else if(e.key==='Tab')closeResults();});
document.addEventListener('input',e=>{if(!e.target||e.target.id!=='mlk-search-input')return;loadSearch();clearTimeout(searchTimer2);searchTimer2=setTimeout(renderResults,60);});
document.addEventListener('focusin',e=>{if(e.target&&e.target.id==='mlk-search-input')loadSearch();});
document.addEventListener('pointerdown',e=>{if(!(e.target&&e.target.closest&&e.target.closest('#mlk-headsearch')))closeResults();},true);
window.addEventListener('blur',()=>setTimeout(()=>{const a=document.activeElement;if(a&&a.tagName==='IFRAME')closeResults();},0));
document.addEventListener('click',e=>{const store=compareStore(),t=e.target&&e.target.closest?e.target:null;if(!t||!store)return;const rm=t.closest('[data-compare-remove]');if(rm){const i=$$('.mlk-tray__remove').indexOf(rm);store.remove(rm.dataset.compareRemove);const next=$$('.mlk-tray__remove')[Math.min(i,$$('.mlk-tray__remove').length-1)]||$('.mlk-tray__clear')||$('#mlk-pagehead .mlk-comparebtn');if(next)next.focus();return;}if(t.closest('[data-compare-clear]')){store.clear();const b=$('#mlk-pagehead .mlk-comparebtn');if(b)b.focus();}});
pages.profile=profile;pages.members=directory;
window.MelangeShell={focusSearch,navigate:go,setHeadInfo(info,frame){if(frame!==undefined&&!(frame&&frame===$('#content.embedded > .mlk-frame-host > .engine-frame')&&frame.getAttribute('data-view')===pageName))return false;headInfo=info&&(info.text||info.html)?{label:info.label||'How to read this',text:info.text||'',html:info.html||''}:null;const t=$('#mlk-pagehead .mlk-pagehead__title');if(t)t.innerHTML=headTitleHTML();return true;},title:()=>headTitle(pageName),view:()=>pageName,deskViews:DESK_VIEWS};
window.ML={$, $$,esc,num,date,pct,money,safe,source,missing,section,table,tr,opt,btn,choose,data,url,memberLink,patchURL,header,workspace,headInfo:setHeadInfo,lede,deskTabs,pageHead,scope,pageControls,pageSelection,bar,billURL,billKey,readStore,manual,saveManual,profileFor,records,timeline,role,economy,sourceList,advanced,contactHistory,render,pages,get catalog(){return catalog;},get params(){return params;},get selected(){return selected;},get pagination(){return pagination;},set pagination(v){pagination=v;},get viewState(){return viewState;},set viewState(v){viewState=v;},set activeRows(v){activeRows=v;}};
document.addEventListener('DOMContentLoaded',async()=>{try{catalog=await data('catalog');const store=compareStore();if(store)store.subscribe(()=>syncCompare());if(window.MLK&&window.MLK.colors)window.MLK.colors().then(()=>{syncTray();const p=$('#mlk-search-panel');if(p&&!p.hidden)renderResults();},()=>{});await render();}catch(e){$('#content').innerHTML=header('Research records unavailable')+missing(e.message)+btn('Reload workspace','reload');$('[data-action=reload]').onclick=()=>location.reload();}});
